VALUES ('1ffebe6a-ca2c-5ab7-b0b4-44fbcea85e2c', 'f04e482f-e537-5022-8fc3-95e6bfd1ba5f', '3e100f9d-42e0-529d-857b-ca5af808236a', '2e402939-832a-5ec4-ae2c-7361b2b91acb', 'External Reference', 'An identifier assigned to the party by an external system or business partner. Preserves a cross-system identity that allows CEDM to reconcile a party with another master-data system. Used for integrations, migration, reconciliation, EDI, synchronization, and external lookup. It is not the canonical CEDM identity; Party.partyId remains the internal identity while externalReference provides interoperability context. Optional when no external system identity exists or when the external identity is maintained elsewhere. Up to 200 characters.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
