VALUES ('c5149a95-e952-5c6f-87ac-07ebc241bb8a', 'bb77f7e3-bcca-50d0-9a9a-cf12b30359c9', 'bf7a76f7-0bc5-5411-8ebb-68793cdfce9c', 'Country', 'Shows one Country at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 2 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
