INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('719df6c0-e903-548e-b57c-45b6ceb9d4d7', 'Bank Transaction', 'Maintain Bank Transaction records', 'Create, find and maintain Bank Transaction records. The list shows every Bank Transaction you have access to — select a row to open it, or use New to add one. Each row is a single Bank Transaction, described by 14 fields.

Id and Transaction Number are unique: no two Bank Transaction records may share the same value, and a save that would duplicate one is rejected. Transaction Number, Transaction Date, Transaction Type, Amount, Status and Account must be filled in before the record can be saved.

Every Bank Transaction points at Currency and Bank Reconciliation. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Bank Transaction then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Bank Transaction with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d15ba492-8a5c-5744-865f-ac76fb9aa90b', 'bus_bank_transaction', 'Bank Transaction', 'Represents external financial-institution evidence of a bank-side movement while keeping reconciliation, internal payment, and accounting meaning separate. BankTransaction says what the bank reported. Payment says what the organization recognized as a payment. PaymentAllocation says how payment is applied to claims. JournalEntry says how the event is recognized in accounting. Central to treasury, bank-feed ingestion, accounts receivable, accounts payable, cash management, reconciliation, audit, fee processing, and accounting. BankAccount provides the statement account. BankTransaction provides external evidence. Payment is the internal settlement event. PaymentAllocation connects settlement to claims. JournalEntry records accounting consequences. Bank statement import → validate source → deduplicate → classify → candidate match Payment → validate account/date/currency/amount/reference → reconcile → Payment may become CLEARED → Invoice settlement remains driven by active PaymentAllocation. Unmatched items remain reconciliation exceptions. Imported/pending → posted → reconciled through a Payment or other accounting treatment; reversal/failure paths remain explicit. Historical statement evidence is retained and corrected through reconciliation events rather than rewriting the source transaction. A bank statement imports a USD 10,000 credit. The system matches it to a USD 10,000 Payment using account, date, currency, amount, and remittance reference. The BankTransaction remains independent evidence, the Payment becomes CLEARED, and its PaymentAllocations settle the applicable invoices. A separate USD 25 bank fee is recorded as bank-side fee evidence and accounting treatment rather than silently reducing the Payment.', 'A', FALSE, FALSE, FALSE, TRUE, '719df6c0-e903-548e-b57c-45b6ceb9d4d7', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('47ac5a4c-b59c-5b0a-acc7-c84a5ccd2111', '719df6c0-e903-548e-b57c-45b6ceb9d4d7', 'd15ba492-8a5c-5744-865f-ac76fb9aa90b', 'Bank Transaction', 'Shows one Bank Transaction at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 6 fields marked with a red asterisk (*) must have a value before Save will accept the record. Currency and Bank Reconciliation are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4d3ef25e-152a-5b55-bec8-ef14ce6cab85', 'd15ba492-8a5c-5744-865f-ac76fb9aa90b', 'id', 'Id', 'Stable identity of the imported bank transaction evidence. Used for statement import, deduplication, reconciliation, audit, and integration. Identifies external evidence and is never substituted for Payment or JournalEntry identity. Provides the root key for bank reconciliation and exception handling. Required for evidence traceability.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ee2632b5-35fa-5cd1-af45-6c2bb9de7a2c', 'd15ba492-8a5c-5744-865f-ac76fb9aa90b', 'transaction_number', 'Transaction Number', 'Bank or internally assigned business reference for the statement transaction. Used for search, duplicate detection, reconciliation, investigation, and bank-feed integration. Must not be assumed to equal Payment.paymentNumber. Provides a primary external reference for candidate matching. Required for operational traceability.', 10, 150, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a8cac0a6-29fb-5b47-8bd8-89841f9734e9', 'd15ba492-8a5c-5744-865f-ac76fb9aa90b', 'transaction_date', 'Transaction Date', 'Timestamp supplied by the bank or statement source for the transaction. Supports statement chronology, reconciliation windows, cash reporting, and investigation. May differ from Payment.paymentDate, Payment.valueDate, accounting posting date, and clearing date. Provides external chronology used in matching and period analysis. Required for bank evidence chronology.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2a85c30e-d48f-5031-add6-d552616b63a0', 'd15ba492-8a5c-5744-865f-ac76fb9aa90b', 'value_date', 'Value Date', 'Bank-provided economic value date for the transaction. Supports cash availability, interest, treasury analysis, reconciliation, and accounting interpretation. Separate from transactionDate because a bank may record and value a transaction on different dates. Provides bank-side settlement timing context. Optional where the bank source does not provide a distinct value date.', 15, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('231c8c4e-97f1-5462-8496-c7ab7658d313', 'd15ba492-8a5c-5744-865f-ac76fb9aa90b', 'transaction_type', 'Transaction Type', 'Classification of the movement reported by the financial institution. Supports matching, cash classification, fee handling, transfer processing, and reconciliation. Bank classification does not by itself determine internal accounting meaning. Helps identify whether evidence is a candidate Payment, fee, transfer, interest, or reversal. Required for reconciliation interpretation.', 1006, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ecc0b6e0-6d7c-5242-a8c2-34d4a674c21d', 'd15ba492-8a5c-5744-865f-ac76fb9aa90b', 'amount', 'Amount', 'Monetary value reported by the bank for this transaction. Used for matching, reconciliation, cash reporting, fee analysis, and accounting comparison. Currency is intrinsic to Money; direct comparison with Payment.amount is permitted only when currencies and applicable amount semantics match. Provides bank-side monetary evidence used to validate Payment clearing. Required for financial reconciliation.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d564b23c-53b4-51b6-a08b-c99a15d7911a', 'd15ba492-8a5c-5744-865f-ac76fb9aa90b', 'status', 'Status', 'Lifecycle state of the bank-reported transaction. Controls whether the transaction is eligible as external settlement evidence. Independent from Payment status and JournalEntry status. POSTED evidence can normally support reconciliation; REVERSED evidence must trigger corresponding correction handling. Required for evidence lifecycle control.', 1005, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8286cefb-5ffe-58ed-8ed3-28302cefddf3', 'd15ba492-8a5c-5744-865f-ac76fb9aa90b', 'reference', 'Reference', 'Bank-provided remittance or transaction reference used to identify the underlying business event. Supports automatic and manual matching to Payment, Invoice, customer remittance, or supplier payment. It is a matching signal, not definitive proof without reconciliation controls. Provides high-value matching evidence. Optional when the bank supplies no usable reference.', 10, 250, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7758919f-900b-54e3-9865-51d0bb37e07c', 'd15ba492-8a5c-5744-865f-ac76fb9aa90b', 'description', 'Description', 'Bank-provided narrative or transaction description. Supports reconciliation, exception investigation, and manual matching. Descriptive evidence may be incomplete or ambiguous and must not override controlled matching rules. Provides secondary matching and investigation context. Optional depending on bank feed quality.', 10, 1000, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cd59604d-813d-5e7f-81d2-4bf2a02ef8d0', 'd15ba492-8a5c-5744-865f-ac76fb9aa90b', 'external_reference', 'External Reference', 'Unique processor, bank, statement-line, or gateway identifier supplied by the external source. Supports idempotent imports and duplicate detection across statement retrievals. External reference is evidence metadata and does not replace bankTransactionId. Prevents duplicate ingestion of the same external transaction. Optional where the source provides no stable external identifier.', 10, 250, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bb644cf0-cd0c-5af6-ad3f-6db6487d83bd', 'd15ba492-8a5c-5744-865f-ac76fb9aa90b', 'currency_id', 'Currency', 'The Currency this BankTransaction belongs to.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c072f38d-92f3-55c5-822b-fbe7e820042a', 'd15ba492-8a5c-5744-865f-ac76fb9aa90b', 'account_id', 'Account', 'Bank account whose statement contains the transaction. Establishes cash-account context and reconciliation scope. Exactly one account is the source context for each BankTransaction. Matching is performed within the account and statement context.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('02475011-a244-5e7d-9bf3-100ec04d8da8', 'd15ba492-8a5c-5744-865f-ac76fb9aa90b', 'counterparty_id', 'Counterparty', 'Bank-reported counterparty when identifiable. Supports candidate matching, sanctions/compliance workflows where applicable, and investigation. Optional because bank evidence may omit or obscure counterparty identity. Provides supporting evidence for Payment matching, not definitive internal party identity.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 130, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
