INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('37cc9494-0dd6-5f37-98e6-8254f61218e3', 'Bank Reconciliation', 'Maintain Bank Reconciliation records', 'Create, find and maintain Bank Reconciliation records. The list shows every Bank Reconciliation you have access to — select a row to open it, or use New to add one. Each row is a single Bank Reconciliation, described by 3 fields.

Id is unique: no two Bank Reconciliation records may share the same value, and a save that would duplicate one is rejected. Bank Account must be filled in before the record can be saved.

Every Bank Reconciliation points at Bank Account. Choose the linked record from the lookup on those fields rather than typing an identifier. Bank Transaction refers back to Bank Reconciliation, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Bank Reconciliation then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Bank Reconciliation with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('08023a11-3e60-5452-9ea4-b378aafb39d8', 'bus_bank_reconciliation', 'Bank Reconciliation', 'A governed reconciliation comparing BankAccount external BankTransaction evidence with internal payments and accounting records for a defined cutoff. Provide canonical enterprise semantics for BankReconciliation. A governed reconciliation comparing BankAccount external BankTransaction evidence with internal payments and accounting records for a defined cutoff. Used in asset, maintenance, treasury, banking, credit-risk, accounting, integration, and audit workflows where applicable. Connects operational or financial lifecycle evidence to canonical masters while keeping accounting, bank, and physical records authoritative in their own domains. Created under governed conditions, progressed or finalized with audit history, and corrected through explicit subsequent evidence. Asset lifecycle, maintenance, treasury operations, bank reconciliation, lending, accounting, reporting, and audit. Enterprise fixed assets, equipment reliability, bank close, FX, deposits, interest, and secured lending.', 'A', FALSE, FALSE, FALSE, TRUE, '37cc9494-0dd6-5f37-98e6-8254f61218e3', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
