INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0c358fb1-1d26-53b7-b208-e9342cb13a5b', 'Bank Loan', 'Maintain Bank Loan records', 'Create, find and maintain Bank Loan records. The list shows every Bank Loan you have access to — select a row to open it, or use New to add one. Each row is a single Bank Loan, described by 10 fields.

Id and Loan Number are unique: no two Bank Loan records may share the same value, and a save that would duplicate one is rejected. Loan Number, Principal Amount, Interest Rate, Start Date, Maturity Date, Status, Borrower, Lender and Currency must be filled in before the record can be saved.

Every Bank Loan points at Currency. Choose the linked record from the lookup on those fields rather than typing an identifier. Collateral refers back to Bank Loan, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Bank Loan then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Bank Loan with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cd271520-4f64-5cc6-a3e0-5cf70f97215b', 'bus_bank_loan', 'Bank Loan', 'Represents a banking entity called BankLoan within the CEDM business model. BankLoan is a business concept with its own identity and lifecycle. It captures information that must remain understandable independently of a database, API, or user interface. Used by business processes, transactions, forms, reports, integrations, and domain capabilities that create, find, change, or relate BankLoan records. The entity participates in a wider business graph through relationships with Party, Organization, Currency. These relationships provide the context needed to interpret the record rather than treating its fields as isolated database columns. The entity lifecycle is governed by its status, invariants, and related business processes. State changes must preserve the declared business meaning and relationships. A typical BankLoan record represents one identifiable business occurrence or master-data object that can be referenced by related CEDM processes.', 'A', FALSE, FALSE, FALSE, TRUE, '0c358fb1-1d26-53b7-b208-e9342cb13a5b', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('41f8b6a5-a6c1-586e-8943-71285f6651a7', '0c358fb1-1d26-53b7-b208-e9342cb13a5b', 'cd271520-4f64-5cc6-a3e0-5cf70f97215b', 'Bank Loan', 'Shows one Bank Loan at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 9 fields marked with a red asterisk (*) must have a value before Save will accept the record. Currency is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c37377a0-d770-5257-a02a-e4e6477ca20e', 'cd271520-4f64-5cc6-a3e0-5cf70f97215b', 'id', 'Id', 'Identifies the loan record associated with this BankLoan. The identifier connects this record to the corresponding CEDM entity so related processes can resolve the correct business object. Used when creating, reviewing, searching, validating, reporting on, or integrating BankLoan records, where applicable. Its meaning is specific to BankLoan; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5f8289d1-2c39-54ef-a1a9-6b3939dcc6c1', 'cd271520-4f64-5cc6-a3e0-5cf70f97215b', 'loan_number', 'Loan Number', 'Captures the business meaning of loan number for the BankLoan. It is interpreted together with the entity''s other attributes and relationships to support the processes that manage this record. Used when creating, reviewing, searching, validating, reporting on, or integrating BankLoan records, where applicable. Its meaning is specific to BankLoan; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fd1c2439-b966-50ab-ab08-6928225eedce', 'cd271520-4f64-5cc6-a3e0-5cf70f97215b', 'principal_amount', 'Principal Amount', 'Captures the business meaning of principal amount for the BankLoan. It is interpreted together with the entity''s other attributes and relationships to support the processes that manage this record. Used when creating, reviewing, searching, validating, reporting on, or integrating BankLoan records, where applicable. Its meaning is specific to BankLoan; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
