-- --------------------------------------------------------------------------
-- Credit (bus_credit)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('caaa0b81-294b-5ddb-a2b8-dab2e550656f', 'Credit', 'Maintain Credit records', 'Create, find and maintain Credit records. The list shows every Credit you have access to — select a row to open it, or use New to add one. Each row is a single Credit, described by 2 fields.

Id is unique: no two Credit records may share the same value, and a save that would duplicate one is rejected. Status must be filled in before the record can be saved.

Every save starts as a Draft. The business rules and workflows attached to Credit then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Credit with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('28921034-5f7a-5251-be2c-3e183661d674', 'bus_credit', 'Credit', 'A governed monetary credit reducing an amount owed or available for application to future or existing charges without itself representing cash payment. Provide canonical enterprise semantics for Credit while keeping planning, operational, financial and evidential responsibilities separated. A governed monetary credit reducing an amount owed or available for application to future or existing charges without itself representing cash payment. Used by applicable finance, treasury, tax, subscription, billing, reporting and integration workflows. References canonical parties and transactions; downstream accounting and cash effects remain explicit through JournalEntry, Payment and BankTransaction where applicable. Created under governed workflow, progressed through explicit states, and retained historically after completion/cancellation. Financial control, tax, billing, subscription management, settlement, reconciliation and audit. Enterprise finance and recurring-revenue operations.', 'A', FALSE, FALSE, FALSE, TRUE, 'caaa0b81-294b-5ddb-a2b8-dab2e550656f', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8c920be6-f3e1-5791-a4e4-c49e8b7860c9', 'caaa0b81-294b-5ddb-a2b8-dab2e550656f', '28921034-5f7a-5251-be2c-3e183661d674', 'Credit', 'Shows one Credit at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e1c4426b-0b17-5a71-87f2-ec7916e3d97b', '28921034-5f7a-5251-be2c-3e183661d674', 'id', 'Id', 'Stable identity of Credit. Identifies one governed Credit record. Enterprise processing, integration, reporting and audit. Referenced by compatible domain workflows. Required.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c99b5e5f-e4ae-547d-806e-072212233a02', '28921034-5f7a-5251-be2c-3e183661d674', 'status', 'Status', 'Governed lifecycle state. Indicates usability/execution state of Credit. Workflow and controls. Historical terminal evidence is retained. Being prepared. Effective or executing. Concluded successfully. Terminated without normal completion. Required.', 1007, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
