INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('177ee915-1065-5008-84e2-8ba2576e7779', 'Collateral', 'Maintain Collateral records', 'Create, find and maintain Collateral records. The list shows every Collateral you have access to — select a row to open it, or use New to add one. Each row is a single Collateral, described by 3 fields.

Id is unique: no two Collateral records may share the same value, and a save that would duplicate one is rejected.

Every Collateral points at Bank Loan. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Collateral then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Collateral with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('49bb1105-8fc8-5e0c-a791-f1c0e20009d4', 'bus_collateral', 'Collateral', 'A governed asset, guarantee, or other value pledged or assigned to secure a BankLoan, Facility, or other credit exposure. Provide canonical enterprise semantics for Collateral. A governed asset, guarantee, or other value pledged or assigned to secure a BankLoan, Facility, or other credit exposure. Used in asset, maintenance, treasury, banking, credit-risk, accounting, integration, and audit workflows where applicable. Connects operational or financial lifecycle evidence to canonical masters while keeping accounting, bank, and physical records authoritative in their own domains. Created under governed conditions, progressed or finalized with audit history, and corrected through explicit subsequent evidence. Asset lifecycle, maintenance, treasury operations, bank reconciliation, lending, accounting, reporting, and audit. Enterprise fixed assets, equipment reliability, bank close, FX, deposits, interest, and secured lending.', 'A', FALSE, FALSE, FALSE, TRUE, '177ee915-1065-5008-84e2-8ba2576e7779', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e5dff2f2-061e-546c-b596-572a32009786', '177ee915-1065-5008-84e2-8ba2576e7779', '49bb1105-8fc8-5e0c-a791-f1c0e20009d4', 'Collateral', 'Shows one Collateral at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. Bank Loan is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
